<?php
$root=dirname(__DIR__,2); $checks=0; $failures=[];
$assert=function(bool $ok,string $label) use (&$checks,&$failures):void{$checks++;if(!$ok)$failures[]=$label;};
$aics=file_get_contents($root.'/aics/fund_ledger.php');
$aicsReport=file_get_contents($root.'/aics/monthly_report.php');
$aicsDash=file_get_contents($root.'/aics/dashboard.php');
$maifip=file_get_contents($root.'/maifip/helpers.php');
$maifipDash=file_get_contents($root.'/maifip/dashboard.php');
$maifipHeader=file_get_contents($root.'/maifip/partials/header.php');
$assert(str_contains($aics,"'BEGINNING BALANCE'") && str_contains($aics,'date_downloaded <= ?'),'AICS selects a dated opening-balance anchor');
$assert(str_contains($aics,"date_downloaded >= ? AND date_downloaded < ?") && str_contains($aics,"COALESCE(batch_no,'')))<>'BEGINNING BALANCE'"),'AICS monthly additions exclude opening balance rows');
$assert(str_contains($aics,"release_date >= ? AND release_date < ?"),'AICS releases are period bounded from anchor date');
$assert(str_contains($aicsReport,'aics_fund_month($pdo,$year,$month)'),'AICS monthly report uses ledger calculation service');
$assert(str_contains($aicsDash,'aics_fund_ledger_position($pdo'),'AICS dashboard uses ledger calculation service');
$assert(str_contains($maifip,'ORDER BY date_downloaded DESC,id DESC LIMIT 1'),'MAIFIP uses one latest valid opening-balance anchor');
$assert(!str_contains($maifip,'if($balance<=0)'),'MAIFIP does not replace zero/negative opening balances with arbitrary first fund row');
$assert(str_contains($maifip,'function maifip_fund_ledger_position'),'MAIFIP dashboard/header use shared facility-scoped ledger position');
$assert(str_contains($maifipDash,'maifip_fund_ledger_position($pdo'),'MAIFIP dashboard uses ledger position');
$assert(str_contains($maifipHeader,'maifip_fund_ledger_position($pdo'),'MAIFIP header uses ledger position');
$assert(str_contains($maifip,"monthly_disbursement_summary") && str_contains($maifip,"record_count"),'MAIFIP preserves monthly-summary fallback only where live release rows are absent');
$openingFn=substr($maifip,strpos($maifip,'function monthly_report_opening_balance'),strpos($maifip,'function maifip_fund_ledger_position')-strpos($maifip,'function monthly_report_opening_balance'));
$anchorBranch=substr($openingFn,strpos($openingFn,'if($anchor){'),strpos($openingFn,'}else{')-strpos($openingFn,'if($anchor){'));
$assert(!str_contains($anchorBranch,'$balance+=(float)$priorAdd') && !str_contains($anchorBranch,'$balance-=(float)$priorRelease'),'MAIFIP opening anchor is not rolled forward twice');
$assert(str_contains($openingFn,'for($m=$firstMonth;$m<$month;$m++)'),'MAIFIP carries forward only completed months after the selected anchor');
$assert(str_contains($openingFn,'release_date>=? AND release_date<?'),'MAIFIP prior releases are bounded to each month and anchor date');
$assert(str_contains($maifip, '$effectiveStart=') && str_contains($maifip, 'date_downloaded>=? AND date_downloaded<?'),'MAIFIP monthly downloaded funds are bounded after a mid-month anchor');
$assert(str_contains(file_get_contents($root.'/aics/config.php'),"const APP_VERSION = '0.0220';") && str_contains(file_get_contents($root.'/maifip/app_version.php'),"const APP_VERSION = '0.0220';"),'Workspace version markers synchronized');
echo 'Fund ledger anchor tests: '.$checks.' checks; '.count($failures).' failures'.PHP_EOL;
foreach($failures as $failure) echo 'FAIL: '.$failure.PHP_EOL;
exit($failures?1:0);
